    exp = inputs['exponent']
    mod = inputs['modulus']

    def matrix_mult(A, B, mod):
        # Multiply two 2x2 matrices mod p
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_power(M, n, mod):
        # Fast exponentiation for matrices
        if n == 1:
            return M
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    result_matrix = matrix_power(M, exp, mod)
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

    return float(total)

